/// A simple TOML subset parser that converts TOML to deterministic JSON.

suberror TomlError {
  DuplicateKey(String)
  ParseError(String)
} derive(Debug)

///|
/// Parse a TOML string into a Json value.
/// Tables become nested objects; dotted keys create nested structure.
pub fn parse_toml(input : StringView) -> Json raise TomlError {
  let root : Map[String, Json] = Map::new()
  let mut current_table = root
  let mut current_path : Array[String] = []
  _parse_lines(input, root, current_table, current_path)
  Json::object(root)
}

///|
fn _parse_lines(
  input : StringView,
  root : Map[String, Json],
  _current_table : Map[String, Json],
  _current_path : Array[String],
) -> Unit raise TomlError {
  let mut table_stack : Array[Map[String, Json]] = [root]
  let mut path_stack : Array[Array[String]] = [[]]

  for line in input.split("\n") {
    let trimmed = line.trim()
    if trimmed.is_empty() || trimmed.has_prefix("#") {
      continue
    }

    // Check if this is a table header
    if trimmed.has_prefix("[") && trimmed.contains("]") {
      let table_content = trimmed.sub(start=1, end=trimmed.length() - 1).trim()
      let keys = table_content.split(".")
      let keys_arr : Array[String] = []
      for k in keys {
        keys_arr.push(k.trim().to_owned())
      }

      // Navigate/create nested structure in root
      let mut parent = root
      let mut current = root
      let mut path_so_far : Array[String] = []
      for i in 0..<keys_arr.length() {
        let key = keys_arr[i]
        path_so_far.push(key)
        if i == keys_arr.length() - 1 {
          // Last key - create or get the table map
          if parent.contains(key) {
            match parent[key] {
              Json::Object(m) => {
                current = m
              }
              _ => {
                let new_map : Map[String, Json] = Map::new()
                parent[key] = Json::object(new_map)
                current = new_map
              }
            }
          } else {
            let new_map : Map[String, Json] = Map::new()
            parent[key] = Json::object(new_map)
            current = new_map
          }
        } else {
          // Intermediate key - ensure it's an object
          if parent.contains(key) {
            match parent[key] {
              Json::Object(m) => {
                current = m
                parent = m
              }
              _ => {
                raise TomlError::ParseError(
                  "Key \(key) is not a table at \(path_so_far.join("."))",
                )
              }
            }
          } else {
            let new_map : Map[String, Json] = Map::new()
            parent[key] = Json::object(new_map)
            parent = new_map
            current = new_map
          }
        }
      }
      table_stack.push(current)
      path_stack.push(path_so_far)
      continue
    }

    // Parse key = value
    let eq_pos = trimmed.find("=")
    if eq_pos == None {
      raise TomlError::ParseError(
        "Invalid line (no '=' found): \(trimmed.to_owned())",
      )
    }
    let eq_idx = eq_pos as! Int
    let key_part = trimmed.sub(start=0, end=eq_idx).trim()
    let value_part = trimmed.sub(start=eq_idx + 1, end=trimmed.length()).trim()

    if key_part.is_empty() {
      raise TomlError::ParseError(
        "Empty key in line: \(trimmed.to_owned())",
      )
    }
    if value_part.is_empty() {
      raise TomlError::ParseError(
        "Empty value in line: \(trimmed.to_owned())",
      )
    }

    let value = parse_value(value_part)?
    let current_map = if table_stack.length() > 0 {
      table_stack[table_stack.length() - 1]
    } else {
      root
    }

    // Handle dotted keys
    if key_part.contains(".") {
      let dot_keys = key_part.split(".")
      let dot_keys_arr : Array[String] = []
      for k in dot_keys {
        dot_keys_arr.push(k.trim().to_owned())
      }
      _set_dotted_key(current_map, dot_keys_arr, value)?
    } else {
      let key_str = key_part.to_owned()
      if current_map.contains(key_str) {
        raise TomlError::DuplicateKey(
          "Duplicate key: \(key_str)",
        )
      }
      current_map[key_str] = value
    }
  }
}

///|
fn _set_dotted_key(
  map : Map[String, Json],
  keys : Array[String],
  value : Json,
) -> Unit raise TomlError {
  if keys.length() == 0 {
    raise TomlError::ParseError("Empty dotted key")
  }
  if keys.length() == 1 {
    let key = keys[0]
    if map.contains(key) {
      raise TomlError::DuplicateKey("Duplicate key: \(key)")
    }
    map[key] = value
    return
  }

  let first_key = keys[0]
  let rest : Array[String] = []
  for i in 1..<keys.length() {
    rest.push(keys[i])
  }

  if !map.contains(first_key) {
    let new_map : Map[String, Json] = Map::new()
    map[first_key] = Json::object(new_map)
  }

  match map[first_key] {
    Json::Object(inner) => {
      _set_dotted_key(inner, rest, value)?
    }
    _ => {
      raise TomlError::ParseError(
        "Key \(first_key) is not a table",
      )
    }
  }
}

///|
fn parse_value(s : StringView) -> Json raise TomlError {
  if s.is_empty() {
    raise TomlError::ParseError("Empty value")
  }

  // String (basic string)
  if s.has_prefix("\"") {
    // Find matching closing quote
    let content = s.sub(start=1, end=s.length())
    let mut result = StringBuilder::new()
    let mut chars = content.iter()
    let mut closed = false
    let mut remaining_start : Int = 0
    loop {
      match chars.next() {
        None => {
          raise TomlError::ParseError("Unclosed string: \(s.to_owned())")
        }
        Some(c) => {
          if c == '"' {
            closed = true
            remaining_start = s.length() - content.length() + content.length() - content.sub(start=content.length() - content.length() + 1, end=content.length()).length() // This doesn't work well
            break
          } else if c == '\\' {
            match chars.next() {
              None => {
                raise TomlError::ParseError(
                  "Unexpected end after escape in string",
                )
              }
              Some(esc) => {
                result.write_char(
                  match esc {
                    '"' => '"'
                    '\\' => '\\'
                    'n' => '\n'
                    't' => '\t'
                    _ => {
                      raise TomlError::ParseError(
                        "Invalid escape: \\\(esc.to_string())",
                      )
                    }
                  },
                )
              }
            }
          } else {
            result.write_char(c)
          }
        }
      }
    }
    if !closed {
      raise TomlError::ParseError("Unclosed string: \(s.to_owned())")
    }
    return Json::string(result.to_string())
  }

  // Boolean
  if s == "true" {
    return Json::boolean(true)
  }
  if s == "false" {
    return Json::boolean(false)
  }

  // Integer
  let is_neg = s.has_prefix("-")
  let num_part = if is_neg { s.sub(start=1, end=s.length()) } else { s }
  if num_part.iter().all(fn(c) { c >= '0' && c <= '9' }) {
    let n : Int = @string.from_str(s) catch {
      _ => {
        raise TomlError::ParseError("Invalid integer: \(s.to_owned())")
      }
    }
    return Json::number(n.to_double(), repr=s.to_owned())
  }

  // Array
  if s.has_prefix("[") {
    // Need to handle nested arrays/values inside brackets
    let content = s.sub(start=1, end=s.length()).trim()
    if content.has_prefix("]") {
      return Json::array([])
    }
    return _parse_array_content(content)
  }

  raise TomlError::ParseError("Unknown value: \(s.to_owned())")
}

///|
fn _parse_array_content(s : StringView) -> Json raise TomlError {
  let mut items : Array[Json] = []
  let mut depth = 0
  let mut current = StringBuilder::new()
  let mut in_string = false
  let mut escaped = false

  for c in s {
    if escaped {
      current.write_char(c)
      escaped = false
      continue
    }
    if c == '\\' && in_string {
      escaped = true
      current.write_char(c)
      continue
    }
    if c == '"' {
      in_string = !in_string
      current.write_char(c)
      continue
    }
    if in_string {
      current.write_char(c)
      continue
    }

    if c == '[' {
      depth = depth + 1
      current.write_char(c)
    } else if c == ']' {
      if depth == 0 {
        // End of array
        let trimmed = current.to_string().trim()
        if !trimmed.is_empty() {
          items.push(parse_value(trimmed.to_string_view())?)
        }
        return Json::array(items)
      } else {
        depth = depth - 1
        current.write_char(c)
      }
    } else if c == ',' && depth == 0 {
      let trimmed = current.to_string().trim()
      if !trimmed.is_empty() {
        items.push(parse_value(trimmed.to_string_view())?)
      }
      current = StringBuilder::new()
    } else {
      current.write_char(c)
    }
  }

  // If we get here, the array wasn't closed
  raise TomlError::ParseError("Unclosed array")
}
"}

