{"path": "/private/tmp/prompt_demos/runs_flash-guidelines/workspaces/01/cmd/tomljson/main.mbt", "content": "///|
/// Convert TOML to JSON.

struct Config {
  stdin : Bool
  path : String
}

///|
fn config_from_matches(matches : @argparse.Matches) -> Config raise {
  let stdin_flag = match matches.flags["stdin"] {
    Some(_) => true
    None => false
  }
  let path = match matches.values["input"] {
    Some(vals) => {
      match vals[0] {
        Some(p) => p
        None => ""
      }
    }
    None => ""
  }
  { stdin: stdin_flag, path }
}

///|
async fn main {
  let config = @argparse.parse(
    Command(
      "tomljson",
      about="Convert TOML to JSON.",
      flags=[
        FlagArg(
          "stdin",
          long="stdin",
          about="Read TOML from stdin instead of a file.",
        ),
      ],
      positionals=[
        PositionArg("input", about="TOML file path."),
      ],
    ),
  )
  let cfg = config_from_matches(config)
  let input = if cfg.stdin {
    @stdio.stdin.read_all().text()
  } else {
