///|
/// A simple TOML subset parser that converts TOML to deterministic JSON.
suberror TomlError {
  DuplicateKey(String)
  ParseError(String)
} derive(Debug)

///|
/// Parse a TOML string into a Json value.
/// Tables become nested objects; dotted keys create nested structure.
pub fn parse_toml(input : StringView) -> Json raise TomlError {
  let root : Map[String, Json] = Map([])
  _parse_lines(input, root)
  Json::object(root)
}

///|
fn _parse_lines(
  input : StringView,
  root : Map[String, Json],
) -> Unit raise TomlError {
  let table_stack : Array[Map[String, Json]] = [root]
  let table_idx = 0

  for line in input.split("\n") {
    let trimmed = line.trim()
    if trimmed.is_empty() || trimmed.has_prefix("#") {
      continue
    }

    // Check if this is a table header like [foo] or [foo.bar]
    if trimmed.has_prefix("[") && trimmed.has_suffix("]") {
      let table_content = trimmed.sub(start=1, end=trimmed.length() - 1).trim()
      let keys : Array[String] = []
      for k in table_content.split(".") {
        keys.push(k.trim().to_owned())
      }
      let table = _ensure_table(root, keys)
      table_stack[table_idx] = table
      continue
    }

    // Parse key = value
    let eq_pos = trimmed.find("=")
    if eq_pos == None {
      raise TomlError::ParseError(
        "Invalid line (no '=' found): \{trimmed.to_owned()}",
      )
    }
    let eq_idx = match eq_pos {
      Some(i) => i
      None => raise TomlError::ParseError("unreachable")
    }
    let key_part = trimmed.sub(start=0, end=eq_idx).trim()
    let value_part = trimmed.sub(start=eq_idx + 1, end=trimmed.length()).trim()

    if key_part.is_empty() {
      raise TomlError::ParseError("Empty key in line: \{trimmed.to_owned()}")
    }
    if value_part.is_empty() {
      raise TomlError::ParseError("Empty value in line: \{trimmed.to_owned()}")
    }

    let value = parse_value(value_part)
    let current_map = table_stack[table_idx]

    // Handle dotted keys like a.b.c = value
    if key_part.contains(".") {
      let dot_keys : Array[String] = []
      for k in key_part.split(".") {
        dot_keys.push(k.trim().to_owned())
      }
      _set_dotted_key(current_map, dot_keys, value)
    } else {
      let key_str = key_part.to_owned()
      if current_map.contains(key_str) {
        raise TomlError::DuplicateKey("Duplicate key: \{key_str}")
      }
      current_map[key_str] = value
    }
  }
}

///|
fn _ensure_table(
  root : Map[String, Json],
  keys : Array[String],
) -> Map[String, Json] raise TomlError {
  if keys.length() == 0 {
    raise TomlError::ParseError("Empty table key")
  }
  let mut current = root
  for i in 0..<keys.length() {
    let key = keys[i]
    if current.contains(key) {
      match current[key] {
        Json::Object(m) => current = m
        _ => raise TomlError::ParseError("Key \{key} is not a table")
      }
    } else {
      let new_map : Map[String, Json] = Map([])
      current[key] = Json::object(new_map)
      current = new_map
    }
  }
  current
}

///|
fn _set_dotted_key(
  map : Map[String, Json],
  keys : Array[String],
  value : Json,
) -> Unit raise TomlError {
  if keys.length() == 0 {
    raise TomlError::ParseError("Empty dotted key")
  }
  if keys.length() == 1 {
    let key = keys[0]
    if map.contains(key) {
      raise TomlError::DuplicateKey("Duplicate key: \{key}")
    }
    map[key] = value
    return
  }

  let first_key = keys[0]
  let rest : Array[String] = []
  for i in 1..<keys.length() {
    rest.push(keys[i])
  }

  if !map.contains(first_key) {
    let new_map : Map[String, Json] = Map([])
    map[first_key] = Json::object(new_map)
  }

  match map[first_key] {
    Json::Object(inner) => _set_dotted_key(inner, rest, value)
    _ => raise TomlError::ParseError("Key \{first_key} is not a table")
  }
}

///|
fn parse_value(s : StringView) -> Json raise TomlError {
  if s.is_empty() {
    raise TomlError::ParseError("Empty value")
  }

  // Boolean
  if s == "true" {
    return Json::boolean(true)
  }
  if s == "false" {
    return Json::boolean(false)
  }

  // Integer
  let mut all_digits_or_sign = true
  for c in s {
    if !((c >= '0' && c <= '9') || c == '-') {
      all_digits_or_sign = false
    }
  }
  if all_digits_or_sign && s.length() > 0 {
    let n : Int = @string.from_str(s) catch {
      _ => raise TomlError::ParseError("Invalid integer: \{s.to_owned()}")
    }
    return Json::number(n.to_double(), repr=s.to_owned())
  }

  // String (basic string)
  if s.has_prefix("\"") {
    let inner = s.sub(start=1, end=s.length())
    return _parse_basic_string(inner)
  }

  // Array
  if s.has_prefix("[") {
    let content = s.sub(start=1, end=s.length()).trim()
    if content.has_prefix("]") {
      return Json::array([])
    }
    return _parse_array_content(content)
  }

  raise TomlError::ParseError("Unknown value: \{s.to_owned()}")
}

///|
fn _parse_basic_string(s : StringView) -> Json raise TomlError {
  let result = StringBuilder::new()
  let mut index = 0
  let len = s.length()
  while index < len {
    let c = match s.get_char(index) {
      Some(ch) => ch
      None => raise TomlError::ParseError("Invalid UTF-8 in string")
    }
    if c == '"' {
      return Json::string(result.to_string())
    } else if c == '\\' {
      index = index + 1
      if index >= len {
        raise TomlError::ParseError("Unexpected end after escape in string")
      }
      let esc = match s.get_char(index) {
        Some(ch) => ch
        None => raise TomlError::ParseError("Invalid UTF-8 in string")
      }
      result.write_char(
        match esc {
          '"' => '"'
          '\\' => '\\'
          'n' => '\n'
          't' => '\t'
          _ =>
            raise TomlError::ParseError("Invalid escape: \\\{esc.to_string()}")
        },
      )
    } else {
      result.write_char(c)
    }
    index = index + 1
  }
  raise TomlError::ParseError("Unclosed string")
}

///|
fn _parse_array_content(s : StringView) -> Json raise TomlError {
  let items : Array[Json] = []
  let mut depth = 0
  let mut current = StringBuilder::new()
  let mut in_string = false

  for c in s {
    if c == '"' {
      in_string = !in_string
      current.write_char(c)
      continue
    }
    if in_string {
      current.write_char(c)
      continue
    }

    if c == '[' {
      depth = depth + 1
      current.write_char(c)
    } else if c == ']' {
      if depth == 0 {
        let trimmed = current.to_string().trim()
        if !trimmed.is_empty() {
          items.push(parse_value(trimmed.to_string_view()))
        }
        return Json::array(items)
      } else {
        depth = depth - 1
        current.write_char(c)
      }
    } else if c == ',' && depth == 0 {
      let trimmed = current.to_string().trim()
      if !trimmed.is_empty() {
        items.push(parse_value(trimmed.to_string_view()))
      }
      current = StringBuilder::new()
    } else {
      current.write_char(c)
    }
  }

  raise TomlError::ParseError("Unclosed array")
}
